import { logger } from "matrix-js-sdk/src/logger";

import SettingsStore from "../../settings/SettingsStore";

const ERROR_EVENTS = new Set(["error"]);

const DEBUG_EVENTS = new Set([
    "abort",
    "canplay",
    "canplaythrough",
    "durationchange",
    "emptied",
    "ended",
    "loadeddata",
    "loadedmetadata",
    "loadstart",
    "pause",
    "play",
    "playing",
    "progress",
    "ratechange",
    "seeked",
    "seeking",
    "stalled",
    "suspend",
    "timeupdate",
    "volumechange",
    "waiting",
]);

/** Public listener for media events on legacy call sound elements. */
export function handleEvent(e: Event): void {
    const element = (e.currentTarget ?? e.target) as HTMLMediaElement | null;
    const details = {
        elementId: element?.id,
        eventType: e.type,
    };

    if (ERROR_EVENTS.has(e.type)) {
        logger.error("Error from legacy call media element", {
            ...details,
            error: element?.error,
        });
    } else if (DEBUG_EVENTS.has(e.type) && SettingsStore.getValue("debug_legacy_call_handler")) {
        logger.debug("Event from legacy call media element", details);
    }
}
